export const lineBreaks = new Set([
    '\u000A', // line feed
    '\u000B', // vertical tab
    '\u000C', // form feed
    '\u000D', // carriage return
    '\u0085', // next line
    '\u2028', // line separator
    '\u2029', // paragraph separator
]);
export const blankSpaces = new Set([
    ...lineBreaks,
    '\u0020', // space
    '\u0009', // horizontal tab
    '\u200E', // left-to-right mark
    '\u200F', // right-to-left mark
]);
